                                                    "payload": {
                                                        "type": "CLIENT_TRANSFORM_SCRIPT",
                                                        "script": {
                                                            "inlineScript": "\n/**\n * @param {params} params\n * @param {api} params.api\n * @param {any} params.event\n */\nfunction evaluateEvent({\n    api,\n    event\n}) {\n    var field_map = event.payload.columnsConfig[0].internalColumnName;\n    var edited_values = event.payload.editValues;\n    var table = event.payload.table;\n    var sys_id = event.payload.taskId;\n      if(!field_map[table]){\n        \n      } \n    var template = [];\n    for (var key in edited_values){\n        var val = edited_values[key].value\n        if(key == 'startDate')\n            val = val + ' 08:00:00';\n        if(key == 'endDate')\n            val = val + ' 17:00:00';\n        var t = field_map[table] + \"=\" + val;\n        template.push(t);\n    }\n    var data = {\n        table: event.payload.task.u_table_name.value,\n        sys_id: sys_id,\n        templatefields: template.join('^'),\n    };\n    return data;\n}",
