                                                        "type": "CLIENT_TRANSFORM_SCRIPT",
                                                        "script": {
                                                            "inlineScript": "/**\n * @param {params} params\n * @param {api} params.api\n * @param {any} params.event\n */\nfunction evaluateEvent({\n    api,\n    event\n}) {\n    // Destructure event payload\n    const {\n        id,\n        newStartDate,\n        newEndDate,\n        direction\n    } = event.payload;\n    const {\n        gantt_data,\n        column_conf\n    } = api.data.project_task_chronology_1.output.result;\n    const modified_task = gantt_data.find(t => t.id === id);\n    if (!modified_task) return;\n    const table = modified_task.u_table_name.value;\n    const start = newStartDate.displayValue.split(' ')[0] + ' 08:00:00';\n    const end = newEndDate.displayValue.split(' ')[0] + ' 17:00:00';\n    const start_date_fieldmap = column_conf.find(c => c.name === 'startDate').internalColumnName;\n    const end_date_fieldmap = column_conf.find(c => c.name === 'endDate').internalColumnName;\n\n    let template = [];\n    if (start_date_fieldmap[table] && direction == \"RESIZE_START\") template.push(start_date_fieldmap[table] + '=' + start);\n    if (end_date_fieldmap[table] && direction == \"RESIZE_END\") template.push(end_date_fieldmap[table] + '=' + end);\n    return {\n        templatefields: template.join(\"^\"),\n        table: table,\n        sys_id: id\n    };\n}",
                                                            "apiVersion": "1.0.0",
