                                                            "inlineScript": "/**\n* @param {params} params\n* @param {api} params.api\n* @param {any} params.event\n*/\nfunction evaluateEvent({api, event}) {\n\tlet url_map = {\n\t\t\"pm_project\": \"now/workspace/project/home/sub/planning/pm_project/\" + event.payload.task.id + \"/\" + Date.now()+\"/params/page-name/planning\",\n\t\t\"pm_project_task\": \"now/workspace/project/home/sub/planning/pm_project/\" + event.payload.task.parent + \"/\" + Date.now()+\"/params/page-name/planning\",\n\t\t\"pm_portfolio\": \"now/nav/ui/classic/params/target/pm_portfolio.do%3Fsys_id%3D\" + event.payload.task.id,\n\t\t\"pm_program\": \"now/nav/ui/classic/params/target/pm_program.do%3Fsys_id%3D\" + event.payload.task.id\n\t};\n\treturn {\n\t\troute: null,\n\t\tfields: null,\n\t\tparams: null,\n\t\tredirect: null,\n\t\tpassiveNavigation: null,\n\t\ttitle: null,\n\t\tmultiInstField: null,\n\t\ttargetRoute: null,\n\t\tnavigationOptions: null,\n\t\texternal: {\n            url: url_map[event.payload.task.u_table_name.value]\n        }\n\t};\n}",
