                            "payload": {
                                "type": "CLIENT_TRANSFORM_SCRIPT",
                                "script": {
                                    "inlineScript": "/**\n * @param {params} params\n * @param {api} params.api\n * @param {any} params.event\n */\nfunction evaluateEvent({\n    api,\n    event\n}) {\n    let msg_obj = {\n        status: 'positive',\n        content: {\n            type: \"html\",\n            value: \"<span>Record has been updated successfully!</span>\"\n        },\n        icon: 'check-strong-fill',\n        id: 'database_update_alert',\n        action: {\n            type: \"dismiss\"\n        },\n    };\n    let {\n        status,\n        message\n    } = event.payload.data.response.result.response;\n    if (status === 'error') {\n        msg_obj.icon = 'database-error-fill';\n        msg_obj.status = 'warning';\n        msg_obj.content.value = \"<span>\" + message.join(\"<br>\") + \"</span>\";\n    }\n    return {\n        items: [msg_obj]\n    };\n}",
                                    "apiVersion": "1.0.0",
                                    "controllerElementId": null,
                                    "scriptSysId": null,
                                    "target": null
                                }
                            },
                            "apiName": "sn_uxf_page.NOW_UXF_PAGE#ADD_NOTIFICATIONS"
                        },
                        "operation": null,
                        "clientScript": null,
                        "conditional": null,
                        "broker": null
